// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { z } from "zod";
export type Product = {
  id: string;
  name: string;
  cents: number;
  note: string;
};
export const PRODUCTS: Product[] = [{
  id: "notebook" as const,
  name: "Field notebook, A5 ruled" as const,
  cents: 1400,
  note: "Stitched, 96 pages" as const
}, {
  id: "tape" as const,
  name: "Washi tape, three rolls" as const,
  cents: 900,
  note: "Dots, stripes, gingham" as const
}, {
  id: "pen" as const,
  name: "Brass pen" as const,
  cents: 2200,
  note: "Refillable, felt tip" as const
}];
export const DEFAULT_QTY = [1, 2, 1];
export const money = (cents: number): string => (cents / 100).toFixed(2);
export type MethodId = "standard" | "express" | "pickup";
export const METHODS: {
  id: MethodId;
  name: string;
  help: string;
  cents: number;
}[] = [{
  id: "standard" as const,
  name: "Standard" as const,
  help: "4 to 6 days. Free over 50.00." as const,
  cents: 490
}, {
  id: "express" as const,
  name: "Express" as const,
  help: "Tomorrow, if you order before 4 pm." as const,
  cents: 990
}, {
  id: "pickup" as const,
  name: "Pick up at the shop" as const,
  help: "12 rue de l'Eau, ready in an hour." as const,
  cents: 0
}];
export const PROMOS: Record<string, {
  label: string;
  percent?: number;
  freeStandard?: boolean;
}> = {
  PAPER10: {
    label: "10% off the paper" as const,
    percent: 10
  },
  FREESHIP: {
    label: "Standard delivery on us" as const,
    freeStandard: true
  }
};
export const FREE_SHIPPING_FROM = 5000;
export const VAT = 23;
export type Totals = {
  subtotal: number;
  discount: number;
  shipping: number;
  vat: number;
  total: number;
};
export function totals(qty: number[], method: MethodId, code: string | null): Totals {
  const subtotal = PRODUCTS.reduce((sum, p, i) => sum + p.cents * (qty[i] ?? 0), 0);
  const promo = code ? PROMOS[code] : undefined;
  const discount = promo?.percent ? Math.round(subtotal * promo.percent / 100) : 0;
  const base = METHODS.find(m => m.id === method)!.cents;
  let shipping = base;
  if (subtotal === 0) shipping = 0;else if (method === "standard" && (subtotal - discount >= FREE_SHIPPING_FROM || promo?.freeStandard)) shipping = 0;else if (method === "express" && promo?.freeStandard) shipping = base - METHODS[0]!.cents;
  const total = subtotal - discount + shipping;
  return {
    subtotal,
    discount,
    shipping,
    vat: Math.round(total * VAT / (100 + VAT)),
    total
  };
}
export function luhn(digits: string): boolean {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return digits.length > 0 && sum % 10 === 0;
}
export function formatCardNumber(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 19);
  if (/^3[47]/.test(d)) return [d.slice(0, 4), d.slice(4, 10), d.slice(10, 15)].filter(Boolean).join(" ");
  return d.replace(/(.{4})/g, "$1 ").trim();
}
export function formatExpiry(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 4);
  if (d.length === 1 && Number(d) > 1) return `0${d}/`;
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d;
}
export type Month = {
  year: number;
  month: number;
};
export function currentMonth(): Month {
  // lint-house-disable-next-line render-time
  const now = new Date();
  return {
    year: now.getFullYear(),
    month: now.getMonth() + 1
  };
}
export const COUNTRIES = ["Portugal", "France", "Germany", "Netherlands", "United Kingdom", "United States"];
export function makeCheckoutSchema(today: Month) {
  return z.object({
    email: z.email("Enter an address like ada@notes.dev."),
    name: z.string().trim().min(2, "Who should we address it to?"),
    address: z.string().trim(),
    city: z.string().trim(),
    postcode: z.string().trim(),
    country: z.string().min(1, "Choose a country."),
    method: z.enum(["standard", "express", "pickup"]),
    cardName: z.string().trim().min(2, "Type the name as it is printed on the card."),
    cardNumber: z.string().refine(v => /^\d{13,19}$/.test(v.replace(/\s/g, "")), "A card number has 13 to 19 digits.").refine(v => luhn(v.replace(/\s/g, "")), "That number does not add up. Check each digit."),
    expiry: z.string().regex(/^(0[1-9]|1[0-2])\/\d{2}$/, "Write it as MM/YY, like 08/28.").refine(v => {
      const [m, y] = v.split("/").map(Number);
      return 2000 + y > today.year || 2000 + y === today.year && m >= today.month;
    }, "That card has expired."),
    cvc: z.string().regex(/^\d{3,4}$/, "The security code is 3 or 4 digits."),
    terms: z.boolean().refine(v => v, "Please tick the box to place the order.")
  }).superRefine((v, ctx) => {
    if (v.method === "pickup") return;
    if (v.address.length < 5) ctx.addIssue({
      code: "custom" as const,
      path: ["address"],
      message: "Where should it go? Add a street and number." as const
    });
    if (v.city.length < 2) ctx.addIssue({
      code: "custom" as const,
      path: ["city"],
      message: "Add the town or city." as const
    });
    if (v.postcode.length < 3) ctx.addIssue({
      code: "custom" as const,
      path: ["postcode"],
      message: "Add the postal code." as const
    });
  });
}
export type CheckoutValues = z.infer<ReturnType<typeof makeCheckoutSchema>>;
export const DEFAULT_VALUES: CheckoutValues = {
  email: "" as const,
  name: "" as const,
  address: "" as const,
  city: "" as const,
  postcode: "" as const,
  country: "Portugal" as const,
  method: "standard" as const,
  cardName: "" as const,
  cardNumber: "" as const,
  expiry: "" as const,
  cvc: "" as const,
  terms: false
};
export const FIELD_LABELS: Partial<Record<keyof CheckoutValues, string>> = {
  email: "Email" as const,
  name: "Full name" as const,
  address: "Street and number" as const,
  city: "Town or city" as const,
  postcode: "Postal code" as const,
  country: "Country" as const,
  cardName: "Name on card" as const,
  cardNumber: "Card number" as const,
  expiry: "Expires" as const,
  cvc: "Security code" as const,
  terms: "The terms" as const
};

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import type { UseFormReturn } from "@/lib/form-bridge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Checkbox } from "@/components/ui/checkbox";
import { Field, FieldContent, FieldDescription, FieldLabel, FieldTitle } from "@/components/ui/field";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Icon } from "@/components/ui/icon";
import { Input } from "@/components/ui/input";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Separator } from "@/components/ui/separator";
import { COUNTRIES, FIELD_LABELS, METHODS, formatCardNumber, formatExpiry, money, type CheckoutValues, type MethodId } from "@/blocks/checkout-01/components/checkout-01-data";
type Props = {
  form: UseFormReturn<CheckoutValues>;
  id: string;
  onSubmit: (e?: UI.BaseSyntheticEvent) => void;
  shipping: Record<MethodId, number>;
};
const Heading = defineUi<{
  n: number;
  children: UI.ReactNode;
}>("Heading", ["n"], (_props, {
  slots: _slots
}) => {
  const n = computed(() => _props["n"]);
  const children = renderValue(() => readSlot(_slots.default));
  return () => {
    return <h3 class="flex items-baseline gap-3 font-script text-3xl leading-none font-semibold">
      <span class="ll-num text-ink-you">{n.value}</span>
      {readSlot(_slots.default)}
    </h3>;
  };
});
const ErrorSummary = defineUi<{
  form: UseFormReturn<CheckoutValues>;
}>("ErrorSummary", ["form"], (_props, {
  slots: _slots
}) => {
  const form = computed(() => _props["form"]);
  const errors = computed(() => form.value.formState.errors);
  const submitCount = computed(() => form.value.formState.submitCount);
  const names = computed(() => (Object.keys(errors.value) as (keyof CheckoutValues)[]).filter(k => errors.value[k]?.message));
  return () => {
    if (!submitCount.value || names.value.length === 0) return null;
    return <Alert variant="destructive">
      <Icon name="circle-alert" />
      <AlertTitle>{names.value.length === 1 ? "One thing needs a look" as const : `${names.value.length} things need a look`}</AlertTitle>
      <AlertDescription>
        <ul class="grid gap-1">
          {names.value.map(k => <li key={k}>
              <button type="button" class="text-start underline decoration-wavy underline-offset-4 outline-offset-2 focus-visible:outline-2 focus-visible:outline-focus" onClick={() => form.value.setFocus(k)}>
                {FIELD_LABELS[k] ?? k}: {errors.value[k]?.message}
              </button>
            </li>)}
        </ul>
      </AlertDescription>
    </Alert>;
  };
});
export const Checkout01Form = defineUi<Props>("Checkout01Form", ["form", "id", "onSubmit", "shipping"], (_props, {
  slots: _slots
}) => {
  const form = computed(() => _props["form"]);
  const id = computed(() => _props["id"]);
  const onSubmit = computed(() => _props["onSubmit"]);
  const shipping = computed(() => _props["shipping"]);
  const method = computed(() => form.value.watch("method"));
  const pickup = computed(() => method.value === "pickup");
  return () => {
    return <Form {...domProps(form.value)}>
      <form id={id.value} novalidate onSubmit={onSubmit.value} aria-label="Checkout" class="@container/form grid gap-8">
        <ErrorSummary form={form.value} />

        <section aria-labelledby={`${id.value}-contact`} class="grid gap-5">
          <div id={`${id.value}-contact`}>
            <Heading n={1}>Who is it for?</Heading>
          </div>
          <FormField control={form.value.control} name="email" render={({
            field
          }) => <FormItem>
                <FormLabel>Email</FormLabel>
                <FormControl>
                  <Input type="email" autocomplete="email" placeholder="ada@notes.dev" {...domProps(field)} />
                </FormControl>
                <FormMessage />
              </FormItem>} />
          <FormField control={form.value.control} name="name" render={({
            field
          }) => <FormItem>
                <FormLabel>Full name</FormLabel>
                <FormControl>
                  <Input autocomplete="name" placeholder="Ada Lovelace" {...domProps(field)} />
                </FormControl>
                <FormMessage />
              </FormItem>} />
        </section>

        <Separator variant="dashed" />

        <section aria-labelledby={`${id.value}-delivery`} class="grid gap-5">
          <div id={`${id.value}-delivery`}>
            <Heading n={2}>Where does it go?</Heading>
          </div>
          <FormField control={form.value.control} name="method" render={({
            field
          }) => <FormItem>
                <FormControl>
                  <RadioGroup value={field.value} onValueChange={field.onChange} aria-label="Delivery" class="gap-3">
                    {METHODS.map(m => <FieldLabel key={m.id} for={`${id.value}-m-${m.id}`}>
                        <Field orientation="horizontal">
                          <FieldContent>
                            <FieldTitle>
                              {m.name}
                              <span class="ll-num ms-auto font-normal">{shipping.value[m.id] === 0 ? "free" as const : `€${money(shipping.value[m.id])}`}</span>
                            </FieldTitle>
                            <FieldDescription>{m.help}</FieldDescription>
                          </FieldContent>
                          <RadioGroupItem value={m.id} id={`${id.value}-m-${m.id}`} />
                        </Field>
                      </FieldLabel>)}
                  </RadioGroup>
                </FormControl>
              </FormItem>} />
          {pickup.value ? <p class="text-sm text-muted-foreground">We will write to you when it is on the counter. Bring the email.</p> : <>
              <FormField control={form.value.control} name="address" render={({
              field
            }) => <FormItem>
                    <FormLabel>Street and number</FormLabel>
                    <FormControl>
                      <Input autocomplete="street-address" placeholder="12 rue de l'Eau" {...domProps(field)} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>} />
              <div class="grid gap-5 @md/form:grid-cols-[1fr_9rem]">
                <FormField control={form.value.control} name="city" render={({
                field
              }) => <FormItem>
                      <FormLabel>Town or city</FormLabel>
                      <FormControl>
                        <Input autocomplete="address-level2" placeholder="Lisbon" {...domProps(field)} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>} />
                <FormField control={form.value.control} name="postcode" render={({
                field
              }) => <FormItem>
                      <FormLabel>Postal code</FormLabel>
                      <FormControl>
                        <Input autocomplete="postal-code" placeholder="1100-148" {...domProps(field)} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>} />
              </div>
              <FormField control={form.value.control} name="country" render={({
              field
            }) => <FormItem>
                    <FormLabel>Country</FormLabel>
                    <FormControl>
                      <NativeSelect autoComplete="country-name" class="w-full" {...domProps(field)}>
                        {COUNTRIES.map(c => <NativeSelectOption key={c} value={c}>
                            {c}
                          </NativeSelectOption>)}
                      </NativeSelect>
                    </FormControl>
                    <FormMessage />
                  </FormItem>} />
            </>}
        </section>

        <Separator variant="dashed" />

        <section aria-labelledby={`${id.value}-pay`} class="grid gap-5">
          <div id={`${id.value}-pay`}>
            <Heading n={3}>How are you paying?</Heading>
          </div>
          <FormField control={form.value.control} name="cardName" render={({
            field
          }) => <FormItem>
                <FormLabel>Name on card</FormLabel>
                <FormControl>
                  <Input autocomplete="cc-name" placeholder="Ada Lovelace" {...domProps(field)} />
                </FormControl>
                <FormMessage />
              </FormItem>} />
          <FormField control={form.value.control} name="cardNumber" render={({
            field
          }) => <FormItem>
                <FormLabel>Card number</FormLabel>
                <InputGroup>
                  <InputGroupAddon>
                    <Icon name="credit-card" />
                  </InputGroupAddon>
                  <FormControl>
                    <InputGroupInput inputmode="numeric" autocomplete="cc-number" placeholder="4242 4242 4242 4242" {...domProps(field)} onChange={(e: Event) => field.onChange(formatCardNumber((e.target as HTMLInputElement).value))} />
                  </FormControl>
                </InputGroup>
                <FormMessage />
              </FormItem>} />
          <div class="grid grid-cols-2 gap-5">
            <FormField control={form.value.control} name="expiry" render={({
              field
            }) => <FormItem>
                  <FormLabel>Expires</FormLabel>
                  <FormControl>
                    <Input inputmode="numeric" autocomplete="cc-exp" placeholder="MM/YY" {...domProps(field)} onChange={(e: Event) => field.onChange(formatExpiry((e.target as HTMLInputElement).value))} />
                  </FormControl>
                  <FormMessage />
                </FormItem>} />
            <FormField control={form.value.control} name="cvc" render={({
              field
            }) => <FormItem>
                  <FormLabel>Security code</FormLabel>
                  <FormControl>
                    <Input inputmode="numeric" autocomplete="cc-csc" placeholder="123" maxlength={4} {...domProps(field)} />
                  </FormControl>
                  <FormMessage />
                </FormItem>} />
          </div>
          <FormField control={form.value.control} name="terms" render={({
            field
          }) => <FormItem>
                <div class="flex items-start gap-3">
                  <FormControl>
                    <Checkbox checked={field.value} onCheckedChange={field.onChange} class="mt-0.5" />
                  </FormControl>
                  <FormLabel class="min-w-0 font-normal leading-snug">I have read the small print: returns within 30 days, in their box.</FormLabel>
                </div>
                <FormMessage />
              </FormItem>} />
        </section>
      </form>
    </Form>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef, useId } from "vue";
import { Button } from "@/components/ui/button";
import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty";
import { FieldError } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Paper } from "@/components/ui/paper";
import { Receipt, ReceiptBarcode, ReceiptDivider, ReceiptFooter, ReceiptHeader, ReceiptLine, ReceiptLines, ReceiptTotal } from "@/components/ui/receipt";
import { Stepper, StepperDecrement, StepperIncrement, StepperInput } from "@/components/ui/stepper";
import { StickyNote, StickyNoteContent } from "@/components/ui/sticky-note";
import { FREE_SHIPPING_FROM, PRODUCTS, PROMOS, VAT, money, type Totals } from "@/blocks/checkout-01/components/checkout-01-data";
type Props = {
  qty: number[];
  onQty: (index: number, value: number) => void;
  code: string | null;
  onCode: (code: string | null) => void;
  totals: Totals;
  formId: string;
  orderNumber: string;
  placing?: boolean;
};
export const Checkout01Summary = defineUi<Props>("Checkout01Summary", ["qty", "onQty", "code", "onCode", "totals", "formId", "orderNumber", "placing"], (_props, {
  slots: _slots
}) => {
  const qty = computed(() => _props["qty"]);
  const onQty = computed(() => _props["onQty"]);
  const code = computed(() => _props["code"]);
  const onCode = computed(() => _props["onCode"]);
  const totals = computed(() => _props["totals"]);
  const formId = computed(() => _props["formId"]);
  const orderNumber = computed(() => _props["orderNumber"]);
  const placing = computed(() => _props["placing"]);
  const draft = shallowRef(initialState(""));
  const setDraft = stateSetter(draft);
  const error = shallowRef(initialState(""));
  const setError = stateSetter(error);
  const promoId = useId();
  const promoInput = shallowRef<HTMLInputElement | null>(null);
  const promoRemove = shallowRef<HTMLButtonElement | null>(null);
  const swapped = shallowRef(false);
  watchDependencies(() => {
    if (!swapped.value) return;
    swapped.value = false;
    if (code.value) promoRemove.value?.focus();else promoInput.value?.focus();
  }, () => [code.value], false);
  const empty = computed(() => qty.value.every(n => n === 0));
  const promo = computed(() => code.value ? PROMOS[code.value] : undefined);
  const apply = computed(() => (e: SubmitEvent) => {
    e.preventDefault();
    const c = draft.value.trim().toUpperCase();
    if (!c) return setError("Type a code first.");
    if (!PROMOS[c]) return setError("That code is not on our list. Check the spelling.");
    setError("");
    setDraft("");
    swapped.value = true;
    onCode.value(c);
  });
  return () => {
    return <div class="grid gap-6">
      <Paper as="section" stock="paper" tilt={0.3} seed="basket" aria-labelledby={`${formId.value}-basket`} class="grid gap-4 p-5">
        <h3 id={`${formId.value}-basket`} class="font-script text-3xl leading-none font-semibold">
          Your basket
        </h3>
        <ul aria-label="Basket" class="grid gap-4">
          {PRODUCTS.map((p, i) => <li key={p.id} class="flex items-center justify-between gap-3">
              <div class="min-w-0">
                <p id={`${formId.value}-p-${p.id}`} class="font-bold">
                  {p.name}
                </p>
                <p class="text-sm text-muted-foreground">
                  {p.note} · <span class="ll-num">€{money(p.cents)}</span>
                </p>
              </div>
              <Stepper value={qty.value[i]} onValueChange={v => onQty.value(i, v ?? 0)} min={0} max={9} aria-labelledby={`${formId.value}-p-${p.id}`}>
                <StepperDecrement aria-label={`One less: ${p.name}`} />
                <StepperInput />
                <StepperIncrement aria-label={`One more: ${p.name}`} />
              </Stepper>
            </li>)}
        </ul>

        <form onSubmit={apply.value} novalidate class="grid gap-2" aria-label="Promo code">
          <Label for={promoId}>Promo code</Label>
          {code.value ? <p class="flex flex-wrap items-center gap-x-3 text-sm">
              <span>
                <b class="font-type">{code.value}</b> applied: {promo.value?.label}.
              </span>
              <Button ref={promoRemove} type="button" variant="link" size="sm" onClick={() => {
              swapped.value = true;
              onCode.value(null);
            }}>
                Remove
              </Button>
            </p> : <>
              <div class="flex gap-2">
                <Input ref={promoInput} id={promoId} placeholder="PAPER10" autocomplete="off" value={draft.value} aria-invalid={!!error.value} aria-describedby={error.value ? `${promoId}-err` : undefined} onChange={(e: Event) => {
                setDraft((e.target as HTMLInputElement).value);
                setError("");
              }} />
                <Button type="submit" variant="outline">
                  Apply
                </Button>
              </div>
              <FieldError id={`${promoId}-err`}>{error.value}</FieldError>
            </>}
        </form>
      </Paper>

      {empty.value ? <Paper as="div" stock="slip" tilt={-0.3} seed="empty-basket">
          <Empty seed="basket-empty" class="p-4 md:p-6">
            <EmptyHeader>
              <EmptyMedia pose="shrug" size={96} />
              <EmptyTitle>Nothing in the basket</EmptyTitle>
              <EmptyDescription>Add a notebook with the plus and the receipt starts writing itself.</EmptyDescription>
            </EmptyHeader>
          </Empty>
        </Paper> : <Receipt as="article" seed="checkout-receipt" aria-label="Your order" class="mx-auto">
          <ReceiptHeader>
            <span>Looseleaf shop</span>
            <span>Order {orderNumber.value}</span>
          </ReceiptHeader>
          <ReceiptLines>
            {PRODUCTS.map((p, i) => qty.value[i] ? <ReceiptLine key={p.id} qty={qty.value[i]} price={money(p.cents * qty.value[i]!)}>
                  {p.name}
                </ReceiptLine> : null)}
          </ReceiptLines>
          <ReceiptLines>
            <ReceiptLine price={money(totals.value.subtotal)}>subtotal</ReceiptLine>
            {totals.value.discount ? <ReceiptLine price={`-${money(totals.value.discount)}`}>code {code.value}</ReceiptLine> : null}
            <ReceiptLine price={totals.value.shipping ? money(totals.value.shipping) : "free" as const}>delivery</ReceiptLine>
            <ReceiptLine price={money(totals.value.vat)}>of which VAT {VAT}%</ReceiptLine>
          </ReceiptLines>
          <ReceiptTotal circled>{money(totals.value.total)}</ReceiptTotal>
          <ReceiptDivider />
          <ReceiptBarcode value={orderNumber.value} />
          <ReceiptFooter>prices in euro, VAT included</ReceiptFooter>
        </Receipt>}

      <p role="status" class="sr-only">
        {empty.value ? "The basket is empty." as const : `Total €${money(totals.value.total)}.`}
      </p>

      <Button type="submit" form={formId.value} size="lg" class="w-full" disabled={empty.value} aria-busy={placing.value}>
        {placing.value ? "Placing your order…" as const : `Pay €${money(totals.value.total)}`}
      </Button>

      <StickyNote color="yellow" fastener="pin" tilt={2} seed="checkout-hint" class="mx-auto mt-3 min-h-0 w-full max-w-56 pb-4">
        <StickyNoteContent class="text-lg leading-snug">
          psst: free delivery over {money(FREE_SHIPPING_FROM)}, and <b class="font-type text-base">PAPER10</b> takes a tenth off the paper.
        </StickyNoteContent>
      </StickyNote>
    </div>;
  };
});

